import { Query as PostgresQuery } from './query.js'

export default function Postgres () {
  const options = {
    database: 'postgres',
    host: ['localhost'],
    port: [5432],
    user: 'postgres',
  }

  function handler (query) {
    return query
  }

  function dispatch (query) {
    function handler (query) {
      return query
    }

    return handler(query)
  }

  return [handler(new PostgresQuery()), dispatch(new PostgresQuery())]
}
